'use server'

import { prisma } from '@/lib/prisma'

export async function getMonthlyReportAction() {
  try {
    const incomes = await prisma.income.findMany();
    const outcomes = await prisma.outcome.findMany();

    const monthlyMap: Record<string, { pemasukan: number; pengeluaran: number }> = {};

    const monthNames = [
      "Januari", "Februari", "Maret", "April", "Mei", "Juni",
      "Juli", "Agustus", "September", "Oktober", "November", "Desember"
    ];

    incomes.forEach((inc) => {
      const d = new Date(inc.date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const key = `${year}-${month}`;
      if (!monthlyMap[key]) {
        monthlyMap[key] = { pemasukan: 0, pengeluaran: 0 };
      }
      monthlyMap[key].pemasukan += Number(inc.amount);
    });

    outcomes.forEach((out) => {
      const d = new Date(out.date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const key = `${year}-${month}`;
      if (!monthlyMap[key]) {
        monthlyMap[key] = { pemasukan: 0, pengeluaran: 0 };
      }
      monthlyMap[key].pengeluaran += Number(out.amount);
    });

    const data = Object.entries(monthlyMap).map(([key, value]) => {
      const [year, month] = key.split('-');
      const monthIdx = parseInt(month) - 1;
      const label = `${monthNames[monthIdx]} ${year}`;
      return {
        bulan: key,
        bulanLabel: label,
        pemasukan: value.pemasukan,
        pengeluaran: value.pengeluaran
      };
    });

    if (data.length === 0) {
      const d = new Date();
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const key = `${year}-${month}`;
      const label = `${monthNames[d.getMonth()]} ${year}`;
      data.push({
        bulan: key,
        bulanLabel: label,
        pemasukan: 0,
        pengeluaran: 0
      });
    }

    return data;
  } catch (err) {
    console.error("getMonthlyReportAction error:", err);
    return [];
  }
}
